// Node inputs are display serializations. The runners construct actual nodes before calling user code.
export const structureGames=[];
function add(number,problem,category,difficulty,fn,args,result,tag,concept,lesson,prompt,cases,extra={}){
 structureGames.push({id:'lc-'+number,number,problem,category,difficulty,fn,params:args.map(a=>a[0]).join(', '),signature:{args,result},structures:true,color:({Tree:'mint','Linked List':'peach',Graph:'lavender',String:'lavender',Heap:'lavender'})[category],tag,time:'8–15 min',concept,description:concept+'.',lesson,hint:lesson,prompt,tests:cases.map(([args,expected])=>({args,expected})),rounds:cases.slice(0,2).map(([args])=>({args})),...extra});
}
